package org.sleepwell.app;
import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
/** Actual original pixel processing and private SQLite; no camera, alarms, providers or runtime. */
public final class PictureNativeTest {
    static byte[] pixels(int seed){byte[] pixels=new byte[128*128];Random random=new Random(seed);int[] blocks=new int[32*32];for(int n=0;n<blocks.length;n++)blocks[n]=35+random.nextInt(185);for(int y=0;y<128;y++)for(int x=0;x<128;x++)pixels[y*128+x]=(byte)blocks[y/4*32+x/4];return pixels;}static PictureSignature signature(){return PictureSignature.from(pixels(41),128,128,0);}static PictureReference reference(){return new PictureReference("Bathroom shelf",signature());}static ChallengeRoutine.Task task(){return new ChallengeRoutine.Task("Picture match",1,0,MathSettings.LEGACY,null,JournalRule.DEFAULT,reference());}
    @Test public void actualPixelPipelineOnAndroidMatchesLikeFramesAndRejectsDifferentBlankDarkCorrupt()throws Exception{PictureSignature reference=signature();byte[] brighter=pixels(41);for(int n=0;n<brighter.length;n++)brighter[n]=(byte)((brighter[n]&255)+8);assertTrue(reference.matches(PictureSignature.from(brighter,128,128,0)));assertFalse(reference.matches(PictureSignature.from(pixels(93),128,128,0)));assertFalse(reference.matches(PictureSignature.from(pixels(41),128,128,90)));byte[] blank=new byte[128*128];Arrays.fill(blank,(byte)128);assertThrows(IllegalArgumentException.class,()->PictureSignature.from(blank,128,128,0));byte[] dark=pixels(41);for(int n=0;n<dark.length;n++)dark[n]=(byte)((dark[n]&255)/12);assertThrows(IllegalArgumentException.class,()->PictureSignature.from(dark,128,128,0));assertThrows(IllegalArgumentException.class,()->PictureSignature.from(new byte[5],128,128,0));PictureReference reopened=PictureReferenceJson.decode(PictureReferenceJson.encode(reference()));assertEquals(reference.key(),reopened.key());}
    @Test public void typedReferenceAndRoutineBoundsRejectCorruptMixedOrUnknownPortableMetadata()throws Exception{JSONObject reference=PictureReferenceJson.encode(reference());for(String key:new String[]{"version","mean","contrast","gradient"}){JSONObject bad=new JSONObject(reference.toString()).put(key,"1");assertThrows(JSONException.class,()->PictureReferenceJson.decode(bad));}for(JSONObject bad:new JSONObject[]{new JSONObject(reference.toString()).put("extra",true),new JSONObject(reference.toString()).put("hash","ABC"),new JSONObject(reference.toString()).put("histogram",new JSONArray()),new JSONObject(reference.toString()).put("mean",0)})assertThrows(JSONException.class,()->PictureReferenceJson.decode(bad));JSONArray encoded=ChallengeRoutineJson.encode(new ChallengeRoutine(List.of(task())));assertEquals(1,ChallengeRoutineJson.decode(encoded).units());JSONObject row=encoded.getJSONObject(0);row.put("rounds",2);assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(encoded));row.put("rounds",1).put("unknown",true);assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(encoded));row.remove("unknown");row.put("type","Math");assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(encoded));assertEquals("Math",ChallengeRoutine.legacy("Picture match",1).tasks.get(0).type);}
    @Test public void privateSaveDefaultsBackupRestoreReopenKeepReferenceAndOneUnitWithoutImages()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm alarm=f.load();alarm.enabled=false;alarm.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Math",1),task())));store.save(alarm);Alarm reopened=store.alarm(1);assertEquals(2,reopened.challenges().units());assertEquals(reference().key(),reopened.challenges().tasks.get(1).picture.key());String template=AlarmDefaultsJson.encode(new AlarmDefaults(reopened));assertEquals(reference().key(),AlarmDefaultsJson.decode(template).create(5).challenges().tasks.get(1).picture.key());JSONObject backup=store.backup();Backup.validate(backup);String original=backup.toString();assertFalse(original.contains("image/jpeg"));assertFalse(original.contains("bitmap"));JSONObject corrupt=new JSONObject(original);corrupt.getJSONArray("alarms").getJSONObject(0).getJSONArray("routine").getJSONObject(1).getJSONObject("picture").put("edges",new JSONArray());assertThrows(JSONException.class,()->Backup.validate(corrupt));assertEquals(original,store.backup().toString());Backup.restoreData(store,backup);assertFalse(store.alarm(1).enabled);assertEquals(reference().key(),store.alarm(1).challenges().tasks.get(1).picture.key());}}
}
